import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class RemindersScreen extends ConsumerWidget{const RemindersScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Bill Reminders')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>showComingSoon(context,'Create reminder form and FCM later'),label:const Text('Create'),icon:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[const ZayloCard(child:Text('Push notifications are not enabled in this MVP. Firebase Cloud Messaging can be connected later.')),for(final b in ref.watch(mockRepositoryProvider).bills()) CheckboxListTile(value:b.paid,onChanged:(_)=>showComingSoon(context,'Mark paid'),title:Text(b.name),subtitle:Text('\$${b.amount} • ${b.frequency} • due ${b.dueDate.day}/${b.dueDate.month}'))]));}
